// ---------------- Playbook level built from the rows above ----------------
const ECFR = { label: 'eCFR 45 CFR Part 164', url: 'https://www.ecfr.gov/current/title-45/subtitle-A/subchapter-C/part-164' };
const EV_TYPE = { S: 'system-generated', R: 'document or record' };
export const citationLine = (r) => [r.soc2.length ? `SOC 2 ${r.soc2.join(', ')}` : '', r.cfr.length ? `45 CFR ${r.cfr.join(', ')}` : ''].filter(Boolean).join(' | ');

export function toTask(r) {
  const c = r.card;
  const check = [
    ...c.check.map((s, i) => `${i + 1}. ${s}`),
    '',
    'Interview questions:',
    ...c.interview.map((q) => `- ${q}`),
    '',
    `Example exception: ${c.exception}`,
  ].join('\n');
  return {
    title: r.title,
    hours: r.hours,
    control: c.control,
    how: c.how,
    check,
    templates: r.templates,
    templatesExclusive: true,
    toBuild: r.toBuild,
    crosswalkId: r.id,
    citationOverride: {
      sections: [citationLine(r)], status: r.mandate, roles: r.roles, source: ECFR,
      note: r.group === 'soc2' ? 'SOC 2 control with no HIPAA requirement behind it.' : `Overlap: ${OVERLAP_LABELS[r.group]}.`,
    },
    evidence: {
      artifacts: c.evidence.map(([t, item]) => `${item} (${EV_TYPE[t]})`),
      sampling: SAMPLING_NOTE,
      pass: 'No exceptions noted.',
      rejection: c.exception,
    },
  };
}

const DAY_ORDER = ['full', 'partial', 'carveout', 'soc2', 'hipaa'];
const DAY_TEXT = {
  full: 'SOC 2 controls whose evidence also satisfies a HIPAA standard, with only small additions.',
  partial: 'SOC 2 controls that help with HIPAA but leave a material gap to close.',
  carveout: 'What the cloud host covers for you, and what your customers must do themselves.',
  soc2: 'Tested in SOC 2 but not required by HIPAA. Keep them for SOC 2; do not present them as HIPAA evidence.',
  hipaa: 'HIPAA requirements a Security-only SOC 2 does not test. Each needs its own work.',
};
export const CROSSWALK_LEVEL = {
  title: 'SOC 2 to HIPAA Crosswalk',
  description: `${CROSSWALK_INTRO} ${ENVIRONMENT_NOTE}`,
  days: DAY_ORDER.map((g) => ({ day: OVERLAP_LABELS[g], label: OVERLAP_LABELS[g], description: DAY_TEXT[g], tasks: CROSSWALK.filter((r) => r.group === g).map(toTask) })),
};
